import ast
def grids_from(content):
    t = str(content)
    out=[]
    pos=0
    while True:
        j = t.find('[[', pos)
        if j<0: break
        depth=0
        for k,ch in enumerate(t[j:], j):
            if ch=='[': depth+=1
            elif ch==']': depth-=1
            if depth==0:
                try: out.append(ast.literal_eval(t[j:k+1]))
                except Exception: pass
                pos=k+1; break
        else:
            break
    return out
